/usr/bin/zsh -lc "node - <<'NODE'
const fs=require('fs');
for (const file of fs.readdirSync('specs',{recursive:true}).filter(f=>f.endsWith('.md'))) {
  const path='specs/'+file;
  const text=fs.readFileSync(path,'utf8');
  for (const m of text.matchAll(/\\[validated by(?:: )?(["'^'"\\]]+)\\]\\(\\.\\.\\/\\.\\.\\/src\\/orchestration\\/chatOrchestrator\\.test\\.ts#L(\\d+)\\)/g)) {
    const lines=fs.readFileSync('src/orchestration/chatOrchestrator.test.ts','utf8').split('\\n');
    const current=lines.findIndex(line=>line.includes("'`it('"'"'${m[1]}'"'"'`))+1;
    console.log(`${path}: ${m[1]} ${m[2]} -> ${current}`);
  }
}
NODE'

/usr/bin/zsh -lc "npx prettier --write specs/hal-engine-architecture/spec.md specs/hal-engine-config-hooks/spec.md && node - <<'NODE'
const fs=require('fs');
let mismatches=[];
for (const file of fs.readdirSync('specs',{recursive:true}).filter(f=>f.endsWith('.md'))) {
  const path='specs/'+file, text=fs.readFileSync(path,'utf8');
  for (const m of text.matchAll(/\\[validated by(?:: )?(["'^'"\\]]+)\\]\\(\\.\\.\\/\\.\\.\\/src\\/orchestration\\/chatOrchestrator\\.test\\.ts#L(\\d+)\\)/g)) {
    const lines=fs.readFileSync('src/orchestration/chatOrchestrator.test.ts','utf8').split('\\n');
    const current=lines.findIndex(line=>line.includes("'`it('"'"'${m[1]}'"'"'`))+1;
    if (current !== Number(m[2])) mismatches.push(`${path}: ${m[1]} ${m[2]} -> ${current}`);
  }
}
if (mismatches.length) { console.error(mismatches.join('"'\\n')); process.exit(1); }
NODE
git diff --check && git diff -- specs/hal-engine-architecture/spec.md specs/hal-engine-config-hooks/spec.md"
